#![no_main]

//! Phase 19 Part A: the primary fuzz target - mirrors production's own
//! exact lex+parse pipeline (`main/check.rs`'s `String::from_utf8_lossy`
//! + `Lexer::tokenize_with_spans` + `Parser::parse_program`) against raw
//! fuzzer-generated bytes.
//!
//! Critical detail: runs on a thread with the same 64MiB `WORKER_STACK_
//! SIZE` production uses, not libFuzzer's own default ~8MiB main-thread
//! stack - without this, the harness would trivially and repeatedly
//! rediscover the already-fixed stack-overflow-on-deep-nesting bug
//! (`main/check.rs`'s own doc comment), drowning out any new finding
//! under a known, closed issue. `MAX_EXPR_DEPTH`'s own panic-based guard
//! (`parser.rs`) is a normal, catchable panic - `libfuzzer-sys`'s own
//! harness already treats a panic as a finding, so no extra
//! `catch_unwind` is needed here for that case; a real crash (stack
//! overflow, a genuine `unreachable!()`/index-out-of-bounds bug) still
//! surfaces as libFuzzer's own real finding.

use libfuzzer_sys::fuzz_target;
use phpstan_rs::lexer::Lexer;
use phpstan_rs::parser::Parser;

const WORKER_STACK_SIZE: usize = 64 * 1024 * 1024;

fuzz_target!(|data: &[u8]| {
    let source = String::from_utf8_lossy(data).into_owned();
    let handle = std::thread::Builder::new()
        .stack_size(WORKER_STACK_SIZE)
        .spawn(move || {
            let tokens = Lexer::new(&source).tokenize_with_spans();
            let _ = Parser::new(tokens).parse_program();
        })
        .expect("failed to spawn fuzz worker thread");
    // A worker panic re-panics on `.join()`'s own `Err`, which
    // `libfuzzer-sys`'s harness catches as a real finding - this join is
    // the mechanism that actually surfaces it, not a value this target
    // has any other use for.
    if let Err(payload) = handle.join() {
        std::panic::resume_unwind(payload);
    }
});
